/**
 * @file        build-bravojs-bundle.js
 * @description Flattens wasm/sofia-wasm.js + wasm/sofia-module.js into one
 *              file wrapped in bravojs's module format (module.declare),
 *              the format DCP's package publisher expects -- see
 *              docs/patching-wasm-libraries-for-dcp.pdf in the Edequity
 *              repo (the same pattern used for duckdbwasm). Local
 *              (unpublished) job.requires() tolerates plain CommonJS
 *              because it goes through a real webpack build at deploy
 *              time; publish does not, so this file is pre-wrapped instead.
 *
 * @usage       node build-bravojs-bundle.js
 *              (run after wasm/build.sh; writes package/sofia-wasm.js)
 */
'use strict';

const fs = require('fs');
const path = require('path');

const WASM_DIR = path.join(__dirname, '..');

const moduleSrc = fs.readFileSync(path.join(WASM_DIR, 'sofia-module.js'), 'utf8');
let wrapperSrc = fs.readFileSync(path.join(WASM_DIR, 'sofia-wasm.js'), 'utf8');

// sofia-wasm.js normally does `const createSofiaModule = require('./sofia-module');`
// In the bundle, createSofiaModule is supplied as a closure parameter instead --
// drop that one line (and only that line; leave everything else, including the
// docblock, untouched for provenance).
const requireLine = "const createSofiaModule = require('./sofia-module');\n\n";
if (!wrapperSrc.includes(requireLine)) {
  throw new Error("expected to find require('./sofia-module') line in sofia-wasm.js");
}
wrapperSrc = wrapperSrc.replace(requireLine, '');
// (the docblock above still mentions require('./sofia-wasm') in prose --
// that's just a comment, not a check target)

const bundle = `/**
 * @file        sofia-wasm.js (published bundle)
 * @description Published-package form of wasm/sofia-wasm.js + wasm/sofia-module.js,
 *              flattened into one file and wrapped in bravojs's module format
 *              (module.declare), per the DCP package publishing convention --
 *              see docs/patching-wasm-libraries-for-dcp.pdf in the Edequity
 *              repo (the same pattern used for duckdbwasm). Generated by
 *              build-bravojs-bundle.js; do not hand-edit -- edit
 *              wasm/sofia-wasm.js or rerun wasm/build.sh + this script instead.
 *
 *              Local (unpublished) job.requires() tolerates plain CommonJS
 *              because it goes through a real webpack build at deploy time;
 *              publish does not, so this file is pre-wrapped instead.
 *
 * @usage       job.requires(['sofia2wasm/sofia-wasm.js']);
 *              // inside the work function:
 *              const sofia = require('sofia-wasm.js');  // bare filename, no ./
 *              const { exitCode, log, files } = await sofia.run({ cube, par });
 */
module.declare([], function (require, exports, module) {
  // ---- sofia-module.js (Emscripten build of SoFiA-2 + wcslib), verbatim ----
  var createSofiaModule = (function () {
    var module = { exports: {} };
    var exports = module.exports;
${moduleSrc}
    return module.exports;
  })();

  // ---- sofia-wasm.js, with require('./sofia-module') replaced by the ----
  // ---- createSofiaModule captured above ----
  var bundleExports = (function (createSofiaModule) {
    var module = { exports: {} };
    var exports = module.exports;
${wrapperSrc}
    return module.exports;
  })(createSofiaModule);

  for (var k in bundleExports) {
    if (Object.prototype.hasOwnProperty.call(bundleExports, k)) exports[k] = bundleExports[k];
  }
});
`;

const outPath = path.join(__dirname, 'sofia-wasm.js');
fs.writeFileSync(outPath, bundle);
console.log(`wrote ${outPath} (${bundle.length} bytes)`);
